    while (descriptor.length() > 0) {
        char current = descriptor.charAt(0);
        if (current == ')') {
            return;
        } else if (current == 'V') {
            // void value, do nothing
        } else if (current == 'L') {
            // object reference, remove the "L" and ";" at the end
            int end = descriptor.indexOf(';');
            descriptor = descriptor.substring(1, end);
        } else {
            // primitive type, remove the "descriptor" and its character
            descriptor = descriptor.substring(1);
        }
    }
}

