    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();
    for (E e : graph.edges()) {
        Pair<List<Pair<Integer,Integer>>,E> entry = new Pair<>(new ArrayList<>(), e);
        separatorList.add(entry);
        for (Pair<V,V> uv : graph.edgesVertices(e)) {
            V u = uv.getFirst();
            V v = uv.getSecond();
            // compute the neighborhood of u, v
            List<V> neighbors = graph.neighborsOf(u);
            // compute list of separators for every pair in subgraph on neighbors
            List<Pair<Integer,Integer>> separators = new ArrayList<>();
            for (int i = 0; i < neighbors.size(); i++) {
                for (int j = i + 1; j < neighbors.size(); j++) {
                    V w1 = neighbors.get(i);
                    V w2 = neighbors.get(j);
                    if (!graph.isEdge(w1, w2)) {
                        Pair<Integer,Integer> separator = new Pair<>(w1.index(), w2.index());
                        separators.add(separator);
                    }
                }
            }
            // add the list of separators to the entry for e
            entry.setFirst(separators);
        }
    }
    return separatorList;
}

